/bin/bash -lc "cd /workspace && python3 -c \"
from openai_client import _extract_text, send_prompt, OpenAIError
# verify text extraction from a realistic Responses payload
payload = {'output': [
    {'type': 'message', 'content': [{'type': 'output_text', 'text': 'Hello"'! '"'}]}
], 'model': 'gpt-4o-mini'}
assert _extract_text(payload) == 'Hello"'!'"'
# missing key raises our error, not a crash
try:
    send_prompt('hi', api_key='')
except OpenAIError as e:
    assert 'No API key' in str(e)
print('self-test OK')
\""

